REPLACE INTO `cms_article` VALUES (1,1,'清远首个人工智能 OPC 生态社区正式揭牌运营','2026 年 8 月 1 日，清城区人工智能 OPC 生态社区在清远星谷科技园正式揭牌运营，从签约到揭牌仅用 21 天，被誉为\"清城速度\"。','2026 年 8 月 1 日，清城区人工智能 OPC 生态社区在清远星谷科技园正式揭牌运营。从 7 月 11 日签约到揭牌仅用 21 天，被誉为\"清城速度\"。揭牌当天，塔链人工智能科技、南京世东智脑、正经点赞（清远）媒体科技等 6 家企业签约入驻，并与广东财贸职业学院、清远职业技术学院、广东岭南职业技术学院 3 所高校共建校外实践教学基地。',NULL,'数智游民创新工场','1','0',188,'2026-08-19 09:45:48','admin','2026-08-21 09:45:48','',NULL),(2,1,'2026 年一季度上新微短剧中 AI 制作占比超 95%','行业数据显示，2025 年国内 AI 视频市场规模已突破 1200 亿元，AI 微短剧、超级数字人等新业态正成为数字经济的重要增长极。','行业数据显示，2025 年国内 AI 视频市场规模已突破 1200 亿元，预计 2030 年达 5800 亿元；2026 年一季度上新微短剧中，AI 制作占比已超过 95%。AI 微短剧、超级数字人、AIGC 内容创作等新业态正在成为数字经济的重要增长极。',NULL,'数智游民创新工场','0','0',132,'2026-08-15 09:45:48','admin','2026-08-21 09:45:48','',NULL),(3,2,'AI 视频市场规模 1200 亿：一人公司主理人的入局机会','2025 年国内 AI 视频市场规模突破 1200 亿元，预计 2030 年达 5800 亿元。对 OPC 主理人而言，AI 内容制作正从\"尝鲜\"走向\"主业\"。','对 OPC（一人公司）主理人而言，AI 内容制作正从\"尝鲜\"走向\"主业\"：一人 + AI 即可完成剧本生成、视频制作、分发投放的全链路。社区面向主理人开放 AI 微短剧制作实战营、超级数字人实操课等课程，并提供订单对接支持，帮助个人创作者以更低门槛切入 AI 内容赛道。',NULL,'数智游民创新工场','0','0',98,'2026-08-17 09:45:48','admin','2026-08-21 09:45:48','',NULL),(4,3,'首届人工智能 OPC 创客短视频创作大赛筹备启动','社区筹办 2026 首届人工智能 OPC 创客短视频创作大赛，并成立创客基金，联动 AI 头部企业对接全国稳定内容订单。','社区筹办 2026 首届人工智能 OPC 创客短视频创作大赛，并成立创客基金。社区将全面梳理文旅推广、政务科普、城市形象等领域的 AI 文创订单需求，联动星火深智等 AI 头部企业对接全国稳定内容订单，以订单和赛事吸引产业集聚。',NULL,'数智游民创新工场','0','0',143,'2026-08-18 09:45:48','admin','2026-08-21 09:45:48','',NULL),(5,4,'毕业生 AI 实训营开营：本地高校学生迈出 OPC 创业第一步','面向本地高校毕业生与清远籍大学生的免费 OPC 创业实训营开营，结营学员将对接社区订单与入驻资源。','面向本地高校毕业生与清远籍大学生的免费 OPC 创业实训营正式开营。实训营覆盖一人公司注册、AI 工具矩阵、内容创作与获客实战全流程，结营学员将对接社区订单与入驻资源，迈出 OPC 创业的第一步。',NULL,'北江人工智能产教融合研究院','0','0',76,'2026-08-20 09:45:48','admin','2026-08-21 09:45:48','',NULL);
